function settleDungeonRoom(state) {
  if (!run) return null;
  if (run.dk !== 'deadmines') { B.endRoom(run, state); return null; }
  if (dungeonRoomReceipts.has(state)) return dungeonRoomReceipts.get(state);
  if (state.encounter !== B.roomKey(run)) return null;
  const receipt = { xp: 0, saved: true };
  dungeonRoomReceipts.set(state, receipt);
  B.endRoom(run, state);
  if (state.result === 'win') {
    const reward = giveXp(B.ENCOUNTERS[state.encounter]);
    receipt.xp = reward.main; syncLevel();
    try { receipt.saved = save() === true; } catch (_) { receipt.saved = false; }
  }
  return receipt;
}

